Here's a sample C++ program that counts the occurrences of a specific word in a text file:

```c++
#include <iostream>
#include <fstream>
#include <string>
#include <cctype>
#include <map>

int main() {
  std::cout << "Enter the name of the file: ";
  std::string filename;
  std::cin >> filename;

  std::cout << "Enter the word you want to count: ";
  std::string search_word;
  std::cin >> search_word;

  std::ifstream file_in(filename);
  if (!file_in.is_open()) {
    std::cout << "Error: Could not open " << filename << "!" << std::endl;
    return 1;
  }

  std::map<std::string, int> word_counts;
  std::string line;
  while (std::getline(file_in, line)) {
    std::istringstream line_stream(line);
    std::string word;
    while (line_stream >> word) {
      if (word == search_word) {
        word_counts[search_word]++;
      }
    }
  }

  std::cout << "Word: " << search_word << ", Occurrences: " << word_counts[search_word] << std::endl;
  file_in.close();

  return 0;
}
```

